package com.blockblastai;
import android.accessibilityservice.*;import android.view.accessibility.*;import android.graphics.*;import android.hardware.HardwareBuffer;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;
public class PlayService extends AccessibilityService {
 Handler h=new Handler(Looper.getMainLooper()); WindowManager wm; LinearLayout panel; TextView status; boolean auto,busy,inGame; int generation; long expected; boolean verify;
 @Override public void onAccessibilityEvent(AccessibilityEvent e){if(e.getEventType()!=AccessibilityEvent.TYPE_WINDOW_STATE_CHANGED||e.getPackageName()==null)return;String p=e.getPackageName().toString();if(p.equals(getPackageName()))return;boolean game=p.equals("com.block.juggle")||p.equals("com.hungrystudio.blockblast")||p.toLowerCase().contains("blockblast");if(game){inGame=true;show();}else if(!p.equals("com.android.systemui")){inGame=false;stop();hide();}}
 @Override public void onInterrupt(){stop();hide();}
 @Override public void onDestroy(){stop();hide();super.onDestroy();}
 void stop(){auto=false;busy=false;verify=false;generation++;if(status!=null)status.setText("Oprit");}
 void hide(){if(panel!=null){wm.removeView(panel);panel=null;}}
 void show(){if(panel!=null)return;wm=(WindowManager)getSystemService(WINDOW_SERVICE);panel=new LinearLayout(this);panel.setOrientation(1);panel.setBackgroundColor(0xff202830);LinearLayout row=new LinearLayout(this);panel.addView(row);button(row,"Hint",()->{stop();capture();});button(row,"Auto",()->{stop();auto=true;capture();});button(row,"Stop",()->stop());status=new TextView(this);status.setTextColor(-1);status.setText("Calibrează înainte de Auto");panel.addView(status);WindowManager.LayoutParams lp=new WindowManager.LayoutParams(-2,-2,WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;wm.addView(panel,lp);}
 void button(LinearLayout r,String s,Runnable a){Button b=new Button(this);b.setText(s);b.setOnClickListener(v->a.run());r.addView(b);}
 float cfg(int i){return Float.parseFloat(getSharedPreferences("cfg",0).getString(MainActivity.KEYS[i],MainActivity.DEFAULTS[i]));}
 int color(Bitmap b,int x,int y){return b.getPixel(Math.max(0,Math.min(b.getWidth()-1,x)),Math.max(0,Math.min(b.getHeight()-1,y)));}
 boolean different(int a,int b){return Math.abs(Color.red(a)-Color.red(b))+Math.abs(Color.green(a)-Color.green(b))+Math.abs(Color.blue(a)-Color.blue(b))>85;}
 void fail(String s){stop();if(status!=null)status.setText(s);}
 void capture(){if(busy||!inGame)return;busy=true;int token=generation;takeScreenshot(Display.DEFAULT_DISPLAY,getMainExecutor(),new TakeScreenshotCallback(){public void onFailure(int code){if(token==generation)fail("Captură indisponibilă: "+code);}public void onSuccess(ScreenshotResult r){HardwareBuffer hb=r.getHardwareBuffer();Bitmap src=Bitmap.wrapHardwareBuffer(hb,r.getColorSpace());Bitmap b=src==null?null:src.copy(Bitmap.Config.ARGB_8888,false);hb.close();if(src!=null)src.recycle();if(token!=generation){if(b!=null)b.recycle();return;}if(b==null){fail("Captură invalidă");return;}try{analyze(b,token);}catch(Exception e){fail("Calibrare / detecție invalidă");}finally{b.recycle();}}});}
 static class Piece {Solver.Shape shape;float sx,sy;int firstX,firstY;Piece(Solver.Shape s,float x,float y,int fx,int fy){shape=s;sx=x;sy=y;firstX=fx;firstY=fy;}}
 void analyze(Bitmap b,int token){float w=b.getWidth(),hh=b.getHeight(),bx=cfg(0)*w,by=cfg(1)*hh,cell=cfg(2)*w/8,ty=cfg(3)*hh,tc=cfg(4)*w;if(cell<=0||tc<=0||bx<0||by<0||bx+cell*8>w||by+cell*8>hh||ty-3*tc<0||ty+3*tc>hh)throw new IllegalArgumentException();int empty=Color.parseColor(getSharedPreferences("cfg",0).getString("emptyColor",MainActivity.DEFAULTS[6]));// Estimate the dominant empty-cell color from dark cell centers, independent of skin hue.
 ArrayList<Integer> samples=new ArrayList<>();for(int y=0;y<8;y++)for(int x=0;x<8;x++)samples.add(color(b,(int)(bx+(x+.5)*cell),(int)(by+(y+.5)*cell)));
 int bestCount=0;for(int a:samples){int count=0;for(int q:samples)if(!different(a,q))count++;int lum=Color.red(a)+Color.green(a)+Color.blue(a);if(lum<Color.red(empty)+Color.green(empty)+Color.blue(empty)||bestCount==0){if(count>=2){empty=a;bestCount=count;}}}
 long board=0;for(int y=0;y<8;y++)for(int x=0;x<8;x++)if(different(color(b,(int)(bx+(x+.5)*cell),(int)(by+(y+.5)*cell)),empty))board|=1L<<(8*y+x);if(verify&&board!=expected){fail("Tabla diferă de predicție. Verifică calibrarea.");return;}verify=false;ArrayList<Piece> pieces=new ArrayList<>();for(int slot=0;slot<3;slot++){float cx=w*(0.21f+slot*0.29f);int bg=color(b,(int)(cx-2.8*tc),(int)(ty-2.8*tc));ArrayList<Integer> xs=new ArrayList<>(),ys=new ArrayList<>();int minx=9,miny=9; // scan centered 5×5 grid; test integer and half-cell offsets
 ArrayList<Integer> bestX=null,bestY=null;int bestOx=0,bestOy=0;for(int ox=0;ox<2;ox++)for(int oy=0;oy<2;oy++){ArrayList<Integer> xx=new ArrayList<>(),yy=new ArrayList<>();for(int j=0;j<5;j++)for(int i=0;i<5;i++){float px=cx+(i-2+ox*.5f)*tc,py=ty+(j-2+oy*.5f)*tc;int a=color(b,(int)px,(int)py);if(different(a,bg)&&different(color(b,(int)(px+.18f*tc),(int)py),bg)&&different(color(b,(int)px,(int)(py+.18f*tc)),bg)){xx.add(i);yy.add(j);}}if(xx.isEmpty()||xx.size()>9||!connected(xx,yy))continue;if(bestX==null||xx.size()>bestX.size()){bestX=xx;bestY=yy;bestOx=ox;bestOy=oy;}}
 if(bestX==null)continue;xs=bestX;ys=bestY;for(int i=0;i<xs.size();i++){minx=Math.min(minx,xs.get(i));miny=Math.min(miny,ys.get(i));}int[] ax=new int[xs.size()],ay=new int[xs.size()];for(int i=0;i<ax.length;i++){ax[i]=xs.get(i)-minx;ay[i]=ys.get(i)-miny;}pieces.add(new Piece(new Solver.Shape(ax,ay),cx+(xs.get(0)-2+bestOx*.5f)*tc,ty+(ys.get(0)-2+bestOy*.5f)*tc,slot,0));}
 ArrayList<Solver.Shape> shapes=new ArrayList<>();for(Piece p:pieces)shapes.add(p.shape);Solver.Move m=Solver.solve(board,shapes);if(m==null){fail("Nicio mutare detectată");return;}status.setText("Piesa detectată "+(pieces.get(m.piece).firstX+1)+" → rând "+(m.y+1)+", col "+(m.x+1));if(!auto){busy=false;return;}Piece p=pieces.get(m.piece);int maxX=0,maxY=0;for(int i=0;i<p.shape.x.length;i++){maxX=Math.max(maxX,p.shape.x[i]);maxY=Math.max(maxY,p.shape.y[i]);}float tx=bx+(m.x+(maxX+1)/2f)*cell,dy=by+(m.y+(maxY+1)/2f)*cell+cfg(5)*hh;if(tx<0||tx>w||dy<0||dy>hh){fail("Țintă în afara ecranului");return;}Path path=new Path();path.moveTo(p.sx,p.sy);path.lineTo(tx,dy);GestureDescription g=new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(path,0,550)).build();expected=m.board;verify=true;boolean ok=dispatchGesture(g,new GestureResultCallback(){public void onCompleted(GestureDescription g){if(token!=generation)return;busy=false;if(auto)h.postDelayed(()->{if(auto&&token==generation)capture();},1100);}public void onCancelled(GestureDescription g){if(token==generation)fail("Gest anulat");}},h);if(!ok)fail("Gest respins");}
 boolean connected(List<Integer>x,List<Integer>y){Set<Integer> s=new HashSet<>();s.add(0);boolean change=true;while(change){change=false;for(int i=0;i<x.size();i++)if(!s.contains(i))for(int j:new ArrayList<>(s))if(Math.abs(x.get(i)-x.get(j))+Math.abs(y.get(i)-y.get(j))==1){s.add(i);change=true;break;}}return s.size()==x.size();}
}
